cypress_script:
describe('User Avatars Profile Links', () => {
  it('should reveal profile link on hover for first user', () => {
    cy.visit('https://the-internet.herokuapp.com/hovers');
    cy.get('div.figure').eq(0).trigger('mouseover');
    cy.get('a').contains('View profile').should('be.visible');
    cy.get('a').contains('View profile').should('have.attr', 'href', '/users/1');
  });

  it('should not change URL when hovering without clicking', () => {
    cy.visit('https://the-internet.herokuapp.com/hovers');
    cy.get('div.figure').eq(0).trigger('mouseover');
    cy.url().should('eq', 'https://the-internet.herokuapp.com/hovers');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('User Avatars Profile Links', () => {
  test('should reveal profile link on hover for first user', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/hovers');
    const firstUserAvatar = page.locator('div.figure').nth(0);
    await firstUserAvatar.hover();
    const profileLink = page.locator('a').withText('View profile');
    await expect(profileLink).toBeVisible();
    await expect(profileLink).toHaveAttribute('href', '/users/1');
  });

  test('should not change URL when hovering without clicking', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/hovers');
    const firstUserAvatar = page.locator('div.figure').nth(0);
    await firstUserAvatar.hover();
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/hovers');
  });
});
